-- TortoiseBotsForever: recruiter greeting texts (issue #298, package P3).
--
-- Forever loads broadcast_text from the hotfixes database, not the world database: apply this file there and
-- the recruiters themselves (forever/sql/world/2026_11_25_01_tortoisebots_hire_recruiters.sql) to the world
-- database. Rows are custom hotfixes (VerifiedBuild = 0), English only, male and female text identical.
-- ID = recruiter entry (PvE-only line) or entry+100 (HireAllowPvP on), the ids the module asks for.
-- Idempotent: the recruiters' text ids are deleted first.

DELETE FROM `broadcast_text` WHERE `ID` BETWEEN 1000000 AND 1000054 OR `ID` BETWEEN 1000100 AND 1000154;

